  align-items: center;
  width: var(--width);
  height: calc(var(--width) / 2.5);
  border-radius: var(--width);
  box-shadow: inset 10px 10px 10px hsl(var(--hue) 20% 80%), inset -10px -10px
      10px hsl(var(--hue) 20% 93%);
}

.indicator {
  content: '';
  position: absolute;
  width: 40%;
  height: 60%;
  transition: all var(--duration) var(--easing);
  box-shadow: inset 0 0 2px hsl(var(--hue) 20% 15% / 60%), inset 0 0 3px 2px hsl(var(
            --hue
          ) 20% 15% / 60%), inset 0 0 5px 2px hsl(var(--hue) 20% 45% / 60%);
}

.indicator.left {
  --hue: var(--accent-hue);
  overflow: hidden;
  left: 10%;
  border-radius: 100px 0 0 100px;
  background: linear-gradient(
    180deg,
    hsl(calc(var(--accent-hue) + 20deg) 95% 80%) 10%,
    hsl(calc(var(--accent-hue) + 20deg) 100% 60%) 30%,
    hsl(var(--accent-hue) 90% 50%) 60%,
    hsl(var(--accent-hue) 90% 60%) 75%,
    hsl(var(--accent-hue) 90% 50%)
  );
}

.indicator.left::after {
  content: '';
  position: absolute;
  opacity: 0.6;
  width: 100%;
  height: 100%;
  background: url('data:image/svg+xml;base64,');
}

.indicator.right {
  right: 10%;
  border-radius: 0 100px 100px 0;
  background-image: linear-gradient(
    180deg,
    hsl(var(--hue) 20% 95%),
    hsl(var(--hue) 20% 65%) 60%,
    hsl(var(--hue) 20% 70%) 70%,
    hsl(var(--hue) 20% 65%)
  );
